# Cloud Architecture Code Examples

Here are practical code examples demonstrating secure, scalable cloud architecture patterns:

## 1. Serverless Function with Defense-in-Depth (Python)

```python
import boto3
import json
from datetime import datetime
from typing import Dict, Any

class SecureServerlessFunction:
    """Secure serverless function with proper error handling and logging"""

    def __init__(self):
        self.sqs = boto3.client('sqs')
        self.logs = boto3.client('logs')

    def process_event(self, event: Dict[str, Any]) -> Dict[str, Any]:
        """Process incoming events with validation and sanitization"""

        # Input validation
        if not self._validate_input(event):
            return self._create_error_response("Invalid input")

        try:
            # Process business logic
            result = self._process_business_logic(event)

            # Log success
            self._log_event("success", event, result)

            return {
                "statusCode": 200,
                "body": json.dumps(result),
                "headers": {"Content-Type": "application/json"}
            }

        except Exception as e:
            # Log error (without sensitive data)
            self._log_event("error", event, str(e))
            return self._create_error_response(str(e))

    def _validate_input(self, event: Dict[str, Any]) -> bool:
        """Validate and sanitize input"""
        if not isinstance(event, dict):
            return False

        # Sanitize inputs
        for key in event:
            if isinstance(event[key], str):
                event[key] = event[key].strip()

        return True

    def _create_error_response(self, message: str) -> Dict[str, Any]:
        """Create standardized error response"""
        return {
            "statusCode": 500,
            "body": json.dumps({"error": message}),
            "headers": {"Content-Type": "application/json"}
        }
```

## 2. Terraform Infrastructure with Security Groups (HCL)

```hcl
# VPC with private subnets for multi-tier architecture
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true

  tags = {
    Name        = "secure-vpc"
    Environment = "production"
  }
}

# Security groups with least-privilege access
resource "aws_security_group" "app_layer" {
  name        = "app-layer-sg"
  description = "Application layer security group"

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]  # Internal only
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# RDS with encryption and VPC endpoints
resource "aws_db_instance" "primary" {
  identifier              = "secure-db"
  engine                  = "aurora-mysql"
  engine_version          = "5.7"
  instance_class          = "db.r5.large"
  allocated_storage       = 100

  # Security settings
  storage_encrypted       = true
  publicly_accessible     = false

  # VPC configuration
  vpc_security_group_ids  = [aws_security_group.app_layer.id]

  # Backup and monitoring
  backup_retention_period = 7
  performance_insights_enabled = true

  tags = {
    Environment = "production"
  }
}

# Lambda with VPC configuration for private data access
resource "aws_lambda_function" "secure_processor" {
  function_name = "secure-data-processor"
  role          = aws_iam_role.lambda_role.arn
  handler       = "index.handler"
  runtime       = "python3.9"

